import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useNavigate, Link } from 'react-router-dom';
import { FaLock, FaEnvelope, FaSignInAlt, FaEye, FaEyeSlash } from 'react-icons/fa';

export default function Login({ orgId, setUser }) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');

        try {
            await API.post(`/auth/${orgId}/login`, { email, password });
            const profileRes = await API.get(`/auth/${orgId}/me`);
            setUser(profileRes.data);

            if (profileRes.data.role === 'customer') {
                navigate('/customer');
            } else if (['worker', 'admin'].includes(profileRes.data.role)) {
                navigate('/worker');
            }
        } catch (err) {
            setError(err.response?.data?.error || 'Invalid credentials');
        }
    };

    return (
        <div className="max-w-md mx-auto bg-gray-800 p-8 rounded-xl border border-gray-700 shadow-xl mt-12 text-white">
            <h2 className="text-2xl font-bold mb-6 text-center flex items-center justify-center gap-2">
                <FaSignInAlt className="text-indigo-400" /> Account Login
            </h2>

            {error && (
                <div className="mb-4 p-3 bg-red-950 border border-red-700 rounded-lg text-sm text-red-200">
                    {error}
                </div>
            )}

            <form onSubmit={handleLogin} className="space-y-4">
                <div>
                    <label className="block text-sm text-gray-400 mb-1">Email Address</label>
                    <input 
                        type="email" 
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                        required
                    />
                </div>
                <div>
                    <label className="block text-sm text-gray-400 mb-1">Password</label>
                    <div className="relative">
                        <input 
                            type={showPassword ? 'text' : 'password'} 
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            className="w-full p-3 pr-10 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            required
                        />
                        <button 
                            type="button" 
                            onClick={() => setShowPassword(!showPassword)}
                            className="absolute inset-y-0 right-0 pr-3 flex items-center text-gray-400 hover:text-white"
                        >
                            {showPassword ? <FaEyeSlash /> : <FaEye />}
                        </button>
                    </div>
                </div>
                <button 
                    type="submit"
                    className="w-full bg-indigo-600 hover:bg-indigo-500 p-3 rounded-lg font-semibold transition"
                >
                    Sign In
                </button>
            </form>
            <p className="mt-4 text-center text-sm text-gray-400">
                Don't have an account? <Link to="/register" className="text-indigo-400 hover:underline">Register</Link>
            </p>
        </div>
    );
}
